/* The build-time shader library (tools/build_shaderlib.py), read in place from the APK.
 *
 * The library is the stored (uncompressed) asset assets/shaders/rdvk_shaderlib.bin.  The app
 * (android/app/app.c) opens it with AAsset_openFileDescriptor64 before the runtime loads and
 * exports FROSTPUNK_RDVK_SHADERLIB=FD:OFFSET:LENGTH; the library maps that range of the APK
 * read-only, so the SPIR-V is paged in from the APK on first use and nothing is copied or
 * translated on the device.  The header must carry the key this library was built with
 * (rdvk_shaderlib_key.h, generated by tools/build_rdvk.py): an APK whose asset belongs to
 * another build declines the native device instead of using wrong shaders. */
#include "shaderlib_device.h"
#include <cerrno>
#include <cstdlib>
#include <cstring>
#include <sys/mman.h>
#include <zlib.h>
#include <unistd.h>
#include "rdvk.h"
#include "rdvk_shaderlib_key.h"   /* generated by tools/build_rdvk.py */

namespace rdvk {
namespace {
const uint8_t* base = nullptr;
size_t length = 0;
const shaderlib::Header* header = nullptr;

template <class T> T read_at(uint32_t offset) { T v; memcpy(&v, base + offset, sizeof(T)); return v; }
}  // namespace

bool shaderlib_open() {
    if (base) return true;
    const char* spec = getenv("FROSTPUNK_RDVK_SHADERLIB");
    char* end = nullptr;
    if (!spec || !*spec) { log("RDVK_SHADERLIB_UNAVAILABLE no packaged shader library (FROSTPUNK_RDVK_SHADERLIB)"); return false; }
    long fd = strtol(spec, &end, 10);
    long long offset = end && *end == ':' ? strtoll(end + 1, &end, 10) : -1;
    long long size = end && *end == ':' ? strtoll(end + 1, &end, 10) : -1;
    if (fd < 0 || offset < 0 || size < (long long)sizeof(shaderlib::Header)) {
        log("RDVK_SHADERLIB_UNAVAILABLE bad FROSTPUNK_RDVK_SHADERLIB=%s", spec);
        return false;
    }
    long page = sysconf(_SC_PAGESIZE);
    long long start = offset - offset % page;
    size_t span = size_t(size + (offset - start));
    void* map = mmap(nullptr, span, PROT_READ, MAP_SHARED, int(fd), off_t(start));
    if (map == MAP_FAILED) {
        log("RDVK_SHADERLIB_UNAVAILABLE mmap fd=%ld offset=%lld bytes=%lld errno=%d", fd, offset, size, errno);
        return false;
    }
    const uint8_t* data = static_cast<const uint8_t*>(map) + (offset - start);
    shaderlib::Header h;
    memcpy(&h, data, sizeof(h));
    uint64_t key;
    memcpy(&key, h.reserved, sizeof(key));
    if (memcmp(h.magic, shaderlib::kMagic, sizeof(h.magic)) || h.version != shaderlib::kVersion || h.total_size != uint64_t(size) ||
        uint64_t(h.shaders) + uint64_t(h.shader_count) * sizeof(shaderlib::Shader) > uint64_t(size) || key != kShaderlibKey) {
        log("RDVK_SHADERLIB_UNAVAILABLE asset does not match this library (version %u, %u bytes, key %016llx, expected %016llx)",
            h.version, h.total_size, (unsigned long long)key, (unsigned long long)kShaderlibKey);
        munmap(map, span);
        return false;
    }
    base = data;
    length = size_t(size);
    header = reinterpret_cast<const shaderlib::Header*>(data);
    log("RDVK_SHADERLIB apk asset shaders=%u bytes=%zu key=%016llx (no shader translator on the device)", h.shader_count, length,
        (unsigned long long)key);
    return true;
}

bool shaderlib_find(const uint8_t* dxbc, size_t size, uint64_t hash, uint32_t alignment, ShaderlibEntry* out) {
    if (!base || size < 20) return false;
    uint32_t lo = 0, hi = read_at<uint32_t>(offsetof(shaderlib::Header, shader_count));
    const uint32_t table = read_at<uint32_t>(offsetof(shaderlib::Header, shaders));
    while (lo < hi) {   /* sorted by (hash, dxbc_size) */
        uint32_t mid = (lo + hi) / 2;
        shaderlib::Shader s = read_at<shaderlib::Shader>(table + mid * uint32_t(sizeof(shaderlib::Shader)));
        if (s.hash < hash || (s.hash == hash && s.dxbc_size < size)) { lo = mid + 1; continue; }
        if (s.hash != hash || s.dxbc_size != size) { hi = mid; continue; }
        if (memcmp(s.checksum, dxbc + 4, 16)) return false;   /* same hash, other container */
        for (uint32_t v = 0; v < s.variant_count; ++v) {
            shaderlib::VariantRecord r = read_at<shaderlib::VariantRecord>(s.variants + v * uint32_t(sizeof(shaderlib::VariantRecord)));
            if (alignment < r.min_alignment || alignment > r.max_alignment) continue;
            uint64_t stored = r.packed_bytes ? uint64_t(r.packed_bytes) : uint64_t(r.spirv_words) * 4;
            if (uint64_t(r.spirv) + stored > length ||
                uint64_t(r.bindings) + uint64_t(r.binding_count) * sizeof(shaderlib::Binding) > length ||
                uint64_t(s.uniform) + s.uniform_size > length)
                return false;
            out->shader = s;
            out->spirv = base + r.spirv;
            out->spirv_words = r.spirv_words;
            out->packed_bytes = r.packed_bytes;
            out->bindings = base + r.bindings;
            out->binding_count = r.binding_count;
            out->uniform = s.uniform_size ? base + s.uniform : nullptr;
            return true;
        }
        return false;
    }
    return false;
}
const uint32_t* shaderlib_spirv(const ShaderlibEntry& entry, std::vector<uint32_t>& scratch) {
    if (!entry.packed_bytes) return reinterpret_cast<const uint32_t*>(entry.spirv);   /* raw words in place */
    scratch.resize(entry.spirv_words);
    uLongf size = uLongf(entry.spirv_words) * 4;
    int rc = uncompress(reinterpret_cast<Bytef*>(scratch.data()), &size, entry.spirv, uLong(entry.packed_bytes));
    if (rc != Z_OK || size != uLongf(entry.spirv_words) * 4) {
        log("RDVK_SHADERLIB_CORRUPT inflate rc=%d bytes=%lu expected=%u", rc, (unsigned long)size, entry.spirv_words * 4);
        return nullptr;
    }
    return scratch.data();
}
}  // namespace rdvk
